; M4a Aga Wait Vbl routine — source candidate for future native Genam build.
; Runtime binary is generated by tools/build_m4a_waitvbl.py.
; Slot 14 state layout inherited unchanged from validated M3b R1:
;   +0  Screen*
;   +4  IntuitionBase
;   +8  GfxBase
;   +12 width
;   +16 height
;   +20 colors
;   +24 modeID
;
; The current HUNK uses the already validated extension-state pointer at
; $01C8(a5). No direct chipset/Copper register is touched.

Gfx_WaitTOF        equ -270
AGA_StatePtr       equ $01C8

; Token:
; dc.w L_AgaWaitVbl,L_Nul
; dc.b "aga wait vb","l"+$80,"I",-1

Aga_WaitVbl_Begin:
    movem.l d0-d7/a0-a2/a4-a6,-(sp)
    movea.l AGA_StatePtr(a5),a2
    tst.l   (a2)                 ; no AGA screen => safe no-op
    beq.s   .Done
    movea.l 8(a2),a6             ; graphics.library base stored by Open
    jsr     Gfx_WaitTOF(a6)
.Done:
    movem.l (sp)+,d0-d7/a0-a2/a4-a6
    rts
